import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  FiAward,
  FiCheck,
  FiEdit2,
  FiImage,
  FiPlus,
  FiRefreshCw,
  FiSearch,
  FiStar,
  FiTrash2,
  FiUser,
  FiX,
} from "react-icons/fi";

import api from "../../services/api";
import { useLanguage } from "../../contexts/LanguageContext";

const EMPTY_FORM = {
  name_en: "",
  name_km: "",
  role_en: "",
  role_km: "",
  company_en: "",
  company_km: "",
  story_en: "",
  story_km: "",
  image: "",
  graduation_year: "",
  is_featured: false,
  is_active: true,
  order: 0,
};

const AdminAlumni = () => {
  const { t, language } = useLanguage();
  const isKhmer = language === "km" || language === "kh";

  // Use one visible form, but keep separate database fields for each language.
  const languageSuffix = isKhmer ? "km" : "en";
  const fieldNames = {
    name: `name_${languageSuffix}`,
    role: `role_${languageSuffix}`,
    company: `company_${languageSuffix}`,
    story: `story_${languageSuffix}`,
  };

  const tr = (key, english, khmer) => {
    const translated = typeof t === "function" ? t(key) : "";

    if (
      translated &&
      translated !== key &&
      !String(translated).includes("undefined")
    ) {
      return translated;
    }

    return isKhmer ? khmer : english;
  };

  const localized = (item, field, fallback = "") => {
    if (!item) return fallback;

    const selectedField = `${field}_${isKhmer ? "km" : "en"}`;
    const value = item[selectedField];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      return value;
    }

    return fallback;
  };

  const [alumni, setAlumni] = useState([]);
  const [formData, setFormData] = useState(EMPTY_FORM);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [imagePreview, setImagePreview] = useState("");
  const [deletingId, setDeletingId] = useState(null);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [featuredFilter, setFeaturedFilter] = useState("all");

  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);

  const [message, setMessage] = useState({
    type: "",
    text: "",
  });

  const API_BASE_URL =
    process.env.REACT_APP_API_URL || "http://127.0.0.1:8000";

  const getImageUrl = (path) => {
    if (!path) return "";

    if (
      String(path).startsWith("http://") ||
      String(path).startsWith("https://")
    ) {
      return path;
    }

    if (String(path).startsWith("/")) {
      return `${API_BASE_URL}${path}`;
    }

    return `${API_BASE_URL}/${path}`;
  };

  const showMessage = (type, text) => {
    setMessage({ type, text });

    window.clearTimeout(showMessage.timer);

    showMessage.timer = window.setTimeout(() => {
      setMessage({ type: "", text: "" });
    }, 4000);
  };

  const getApiErrorMessage = (error) => {
    const detail = error?.response?.data?.detail;

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    if (typeof detail === "string") {
      return detail;
    }

    return (
      error?.response?.data?.message ||
      error?.message ||
      tr("alumni.operationFailed", "Something went wrong. Please try again.", "មានបញ្ហាកើតឡើង។ សូមព្យាយាមម្ដងទៀត។")
    );
  };

  const fetchAlumni = useCallback(async () => {
    try {
      setLoading(true);

      /*
       * Admin endpoint returns active and inactive records.
       * Authorization is expected to be added by your shared api instance.
       */
      const response = await api.get("/api/alumni/admin/all", {
        params: {
          skip: 0,
          limit: 200,
        },
      });

      const data = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.items)
        ? response.data.items
        : [];

      setAlumni(data);
    } catch (error) {
      console.error("Fetch alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
      setAlumni([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAlumni();
  }, [fetchAlumni]);

  const filteredAlumni = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    return alumni.filter((item) => {
      const searchableText = [
        item.name_en,
        item.name_km,
        item.role_en,
        item.role_km,
        item.company_en,
        item.company_km,
        item.graduation_year,
      ]
        .filter((value) => value !== null && value !== undefined)
        .join(" ")
        .toLowerCase();

      const matchesSearch =
        keyword === "" || searchableText.includes(keyword);

      const matchesStatus =
        statusFilter === "all" ||
        (statusFilter === "active" && item.is_active) ||
        (statusFilter === "inactive" && !item.is_active);

      const matchesFeatured =
        featuredFilter === "all" ||
        (featuredFilter === "featured" && item.is_featured) ||
        (featuredFilter === "regular" && !item.is_featured);

      return matchesSearch && matchesStatus && matchesFeatured;
    });
  }, [alumni, search, statusFilter, featuredFilter]);

  const stats = useMemo(() => {
    return {
      total: alumni.length,
      active: alumni.filter((item) => item.is_active).length,
      featured: alumni.filter((item) => item.is_featured).length,
      inactive: alumni.filter((item) => !item.is_active).length,
    };
  }, [alumni]);

  const clearImagePreview = () => {
    if (imagePreview) {
      URL.revokeObjectURL(imagePreview);
    }

    setImagePreview("");
  };

  const resetForm = () => {
    clearImagePreview();
    setFormData(EMPTY_FORM);
    setEditingId(null);
    setShowForm(false);
  };

  const openCreateForm = () => {
    clearImagePreview();
    setFormData(EMPTY_FORM);
    setEditingId(null);
    setShowForm(true);
  };

  const openEditForm = (item) => {
    clearImagePreview();
    setEditingId(item.id);

    setFormData({
      name_en: item.name_en || "",
      name_km: item.name_km || "",
      role_en: item.role_en || "",
      role_km: item.role_km || "",
      company_en: item.company_en || "",
      company_km: item.company_km || "",
      story_en: item.story_en || "",
      story_km: item.story_km || "",
      image: item.image || "",
      graduation_year:
        item.graduation_year !== null &&
        item.graduation_year !== undefined
          ? String(item.graduation_year)
          : "",
      is_featured: Boolean(item.is_featured),
      is_active:
        item.is_active === undefined ? true : Boolean(item.is_active),
      order:
        item.order !== null && item.order !== undefined
          ? Number(item.order)
          : 0,
    });

    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleChange = (event) => {
    const { name, value, type, checked } = event.target;

    setFormData((previous) => ({
      ...previous,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleImageUpload = async (event) => {
    const input = event.target;
    const file = input.files?.[0];

    if (!file) return;

    const allowedTypes = ["image/jpeg", "image/png", "image/webp"];

    if (!allowedTypes.includes(file.type)) {
      showMessage(
        "error",
        isKhmer
          ? "អនុញ្ញាតតែរូបភាព JPG, PNG និង WEBP ប៉ុណ្ណោះ។"
          : "Only JPG, PNG and WEBP images are allowed."
      );
      input.value = "";
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      showMessage(
        "error",
        isKhmer
          ? "ទំហំរូបភាពមិនត្រូវលើសពី 5MB។"
          : "Image size must not exceed 5 MB."
      );
      input.value = "";
      return;
    }

    clearImagePreview();
    const temporaryPreview = URL.createObjectURL(file);
    setImagePreview(temporaryPreview);

    const uploadData = new FormData();
    uploadData.append("file", file);

    try {
      setUploadingImage(true);

      const response = await api.post("/api/alumni/upload", uploadData);
      const uploadedPath = response.data?.path || response.data?.url;

      if (!uploadedPath) {
        throw new Error("Backend did not return an image path.");
      }

      setFormData((previous) => ({
        ...previous,
        image: uploadedPath,
      }));

      showMessage(
        "success",
        isKhmer
          ? "បានបញ្ចូលរូបភាពដោយជោគជ័យ។"
          : "Image uploaded successfully."
      );
    } catch (error) {
      console.error("Upload alumni image error:", error);
      clearImagePreview();
      showMessage("error", getApiErrorMessage(error));
    } finally {
      setUploadingImage(false);
      input.value = "";
    }
  };

  const removeSelectedImage = () => {
    clearImagePreview();
    setFormData((previous) => ({
      ...previous,
      image: "",
    }));
  };

  const buildPayload = () => {
    return {
      name_en: formData.name_en.trim(),
      name_km: formData.name_km.trim() || null,

      role_en: formData.role_en.trim() || null,
      role_km: formData.role_km.trim() || null,

      company_en: formData.company_en.trim() || null,
      company_km: formData.company_km.trim() || null,

      story_en: formData.story_en.trim() || null,
      story_km: formData.story_km.trim() || null,

      image: formData.image.trim() || null,

      graduation_year:
        formData.graduation_year === ""
          ? null
          : Number(formData.graduation_year),

      is_featured: Boolean(formData.is_featured),
      is_active: Boolean(formData.is_active),
      order: Number(formData.order) || 0,
    };
  };

  const validateForm = () => {
    const currentNameField = fieldNames.name;

    if (!formData[currentNameField]?.trim()) {
      showMessage(
        "error",
        isKhmer
          ? "សូមបញ្ចូលឈ្មោះជាភាសាខ្មែរ។"
          : "Please enter the alumni name in English."
      );
      return false;
    }

    if (
      formData.graduation_year !== "" &&
      (!Number.isInteger(Number(formData.graduation_year)) ||
        Number(formData.graduation_year) < 1900 ||
        Number(formData.graduation_year) > 2100)
    ) {
      showMessage(
        "error",
        tr("alumni.invalidGraduationYear", "Graduation year must be between 1900 and 2100.", "ឆ្នាំបញ្ចប់ការសិក្សាត្រូវស្ថិតចន្លោះឆ្នាំ 1900 និង 2100។")
      );
      return false;
    }

    return true;
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!validateForm()) return;

    try {
      setSaving(true);

      const payload = buildPayload();

      if (editingId) {
        await api.put(`/api/alumni/${editingId}`, payload);
        showMessage("success", tr("alumni.updatedSuccess", "Alumni updated successfully.", "បានកែប្រែព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      } else {
        await api.post("/api/alumni/", payload);
        showMessage("success", tr("alumni.createdSuccess", "Alumni created successfully.", "បានបង្កើតព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      }

      resetForm();
      await fetchAlumni();
    } catch (error) {
      console.error("Save alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (item) => {
    const displayName =
      localized(
        item,
        "name",
        item.name_en || item.name_km || ""
      ) ||
      tr(
        "alumni.thisAlumni",
        "this alumni",
        "អតីតសិស្សនេះ"
      );

    const confirmed = window.confirm(
      tr(
        "alumni.deleteConfirm",
        `Delete "${displayName}"?`,
        `តើអ្នកប្រាកដថាចង់លុប "${displayName}" មែនទេ?`
      )
    );

    if (!confirmed) return;

    try {
      setDeletingId(item.id);

      await api.delete(`/api/alumni/${item.id}`);

      showMessage("success", tr("alumni.deletedSuccess", "Alumni deleted successfully.", "បានលុបព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      await fetchAlumni();
    } catch (error) {
      console.error("Delete alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    } finally {
      setDeletingId(null);
    }
  };

  const handleQuickUpdate = async (item, field) => {
    try {
      const payload = {
        [field]: !item[field],
      };

      await api.put(`/api/alumni/${item.id}`, payload);

      setAlumni((previous) =>
        previous.map((record) =>
          record.id === item.id
            ? {
                ...record,
                ...payload,
              }
            : record
        )
      );

      showMessage(
        "success",
        field === "is_active"
          ? tr("alumni.statusUpdated", "Status updated.", "បានធ្វើបច្ចុប្បន្នភាពស្ថានភាព។")
          : tr("alumni.featuredUpdated", "Featured status updated.", "បានធ្វើបច្ចុប្បន្នភាពស្ថានភាពពិសេស។")
      );
    } catch (error) {
      console.error("Quick update alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    }
  };

  return (
    <div className={`w-full min-h-screen p-6 bg-[#F0F7FF] ${isKhmer ? "font-khmer" : "font-english"}`}>
      <div className="w-full max-w-[1450px] mx-auto">
        
        {/* =====================================================
            HEADER
        ====================================================== */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-8">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-[#0D1B3E] text-white flex items-center justify-center shadow-md flex-shrink-0">
              <FiAward size={22} />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-[#0D1B3E] leading-tight">
                {tr("alumni.management", "Alumni Management", "គ្រប់គ្រងអតីតសិស្ស")}
              </h1>
              <p className="text-sm text-[#6B8AFF] mt-0.5">
                {tr("alumni.subtitle", "Create, update and manage alumni profiles shown on the SC Academy website.", "បង្កើត កែប្រែ និងគ្រប់គ្រងព័ត៌មានអតីតសិស្សដែលបង្ហាញលើគេហទំព័រ SC Academy។")}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={openCreateForm}
            className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#C23636] text-white px-5 text-sm font-semibold shadow-sm transition hover:bg-[#A92E2E]"
          >
            <FiPlus size={18} />
            {tr("alumni.addAlumni", "Add Alumni", "បន្ថែមអតីតសិស្ស")}
          </button>
        </div>

        {/* =====================================================
            MESSAGE
        ====================================================== */}
        {message.text && (
          <div
            className={`mb-6 flex items-center justify-between rounded-xl border px-4 py-3 text-sm font-semibold ${
              message.type === "success"
                ? "border-[#EBF9F0] bg-[#EBF9F0] text-[#2E7D32]"
                : "border-[#FFEBEE] bg-[#FFEBEE] text-[#C62828]"
            }`}
          >
            <div className="flex items-center gap-2">
              {message.type === "success" ? (
                <FiCheck size={18} />
              ) : (
                <FiX size={18} />
              )}
              {message.text}
            </div>
            <button
              type="button"
              onClick={() => setMessage({ type: "", text: "" })}
              className="p-1 rounded-md transition hover:bg-black/5"
            >
              <FiX size={18} />
            </button>
          </div>
        )}

        {/* =====================================================
            STATS
        ====================================================== */}
        <div className="grid grid-cols-2 xl:grid-cols-4 gap-5 mb-8">
          {[
            {
              title: tr("alumni.totalAlumni", "Total Alumni", "អតីតសិស្សសរុប"),
              value: stats.total,
              icon: FiUser,
            },
            {
              title: tr("common.active", "Active", "សកម្ម"),
              value: stats.active,
              icon: FiCheck,
            },
            {
              title: tr("common.featured", "Featured", "ពិសេស"),
              value: stats.featured,
              icon: FiStar,
            },
            {
              title: tr("common.inactive", "Inactive", "អសកម្ម"),
              value: stats.inactive,
              icon: FiX,
            },
          ].map((stat) => {
            const Icon = stat.icon;
            return (
              <div key={stat.title} className="bg-white rounded-xl border border-[#F0F4FB] p-5 shadow-sm">
                <div className="flex items-center justify-between gap-4">
                  <div>
                    <p className="text-sm text-[#6B8AFF]">
                      {stat.title}
                    </p>
                    <p className="text-2xl font-bold text-[#0D1B3E] mt-1">
                      {stat.value}
                    </p>
                  </div>
                  <div className="h-10 w-10 rounded-xl bg-[#F0F7FF] text-[#0D1B3E] flex items-center justify-center">
                    <Icon size={18} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* =====================================================
            FORM
        ====================================================== */}
        {showForm && (
          <div className="mb-6 bg-white border border-[#F0F4FB] rounded-xl shadow-sm overflow-hidden">
            <div className="flex items-center justify-between gap-4 border-b border-[#E8EEF9] px-6 py-4">
              <div>
                <p className="text-xs font-bold uppercase tracking-wider text-[#C23636]">
                  {tr("alumni.form", "Alumni Form", "ទម្រង់ព័ត៌មានអតីតសិស្ស")}
                </p>
                <h2 className="text-xl font-bold text-[#0D1B3E] mt-0.5">
                  {editingId ? tr("alumni.editAlumni", "Edit Alumni", "កែប្រែអតីតសិស្ស") : tr("alumni.createAlumni", "Create Alumni", "បង្កើតអតីតសិស្ស")}
                </h2>
              </div>
              <button
                type="button"
                onClick={resetForm}
                disabled={saving}
                className="h-9 w-9 rounded-lg border border-[#E8EEF9] text-[#6B8AFF] transition hover:border-[#C23636] hover:bg-[#FFEBEE] hover:text-[#C23636] flex items-center justify-center"
              >
                <FiX size={18} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6">
              <div className="grid grid-cols-1 gap-6 xl:grid-cols-[1fr_340px]">
                <div className="space-y-6">
                  <fieldset className="border border-[#E8EEF9] rounded-xl p-5 bg-white">
                    <legend className="px-2 text-xs font-bold text-[#0D1B3E]">
                      {isKhmer ? "ព័ត៌មានជាភាសាខ្មែរ" : "English Information"}
                    </legend>
                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                      <InputField
                        label={isKhmer ? "ឈ្មោះ" : "Name"}
                        name={fieldNames.name}
                        value={formData[fieldNames.name]}
                        onChange={handleChange}
                        required
                        placeholder={isKhmer ? "ឈ្មោះពេញរបស់អតីតសិស្ស" : "Alumni full name"}
                      />
                      <InputField
                        label={isKhmer ? "តួនាទី / មុខតំណែង" : "Role / Position"}
                        name={fieldNames.role}
                        value={formData[fieldNames.role]}
                        onChange={handleChange}
                        placeholder={isKhmer ? "តួនាទី ឬមុខតំណែង" : "Software Developer"}
                      />
                      <InputField
                        label={isKhmer ? "ក្រុមហ៊ុន / ស្ថាប័ន" : "Company / Institution"}
                        name={fieldNames.company}
                        value={formData[fieldNames.company]}
                        onChange={handleChange}
                        placeholder={isKhmer ? "ក្រុមហ៊ុន ឬសាកលវិទ្យាល័យ" : "Company or university"}
                        wrapperClassName="md:col-span-2"
                      />
                      <TextareaField
                        label={isKhmer ? "រឿងរ៉ាវជោគជ័យ" : "Story"}
                        name={fieldNames.story}
                        value={formData[fieldNames.story]}
                        onChange={handleChange}
                        placeholder={isKhmer ? "សរសេរអំពីរឿងរ៉ាវជោគជ័យរបស់អតីតសិស្ស..." : "Write the alumni success story..."}
                        wrapperClassName="md:col-span-2"
                      />
                    </div>
                  </fieldset>

                  <fieldset className="border border-[#E8EEF9] rounded-xl p-5 bg-white">
                    <legend className="px-2 text-xs font-bold text-[#0D1B3E]">
                      {tr("alumni.displaySettings", "Display Settings", "ការកំណត់ការបង្ហាញ")}
                    </legend>
                    <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                      <InputField
                        label={tr("alumni.graduationYear", "Graduation Year", "ឆ្នាំបញ្ចប់ការសិក្សា")}
                        name="graduation_year"
                        type="number"
                        min="1900"
                        max="2100"
                        value={formData.graduation_year}
                        onChange={handleChange}
                        placeholder="2024"
                      />
                      <InputField
                        label={tr("alumni.displayOrder", "Display Order", "លំដាប់បង្ហាញ")}
                        name="order"
                        type="number"
                        min="0"
                        value={formData.order}
                        onChange={handleChange}
                        placeholder="0"
                      />
                      <div className="flex flex-col justify-end gap-3 rounded-xl bg-[#F0F7FF] p-4 border border-[#E8EEF9]">
                        <CheckboxField
                          label={tr("common.active", "Active", "សកម្ម")}
                          name="is_active"
                          checked={formData.is_active}
                          onChange={handleChange}
                        />
                        <CheckboxField
                          label={tr("alumni.featuredOnHome", "Featured on Home", "បង្ហាញពិសេសលើទំព័រដើម")}
                          name="is_featured"
                          checked={formData.is_featured}
                          onChange={handleChange}
                        />
                      </div>
                    </div>
                  </fieldset>
                </div>

                {/* IMAGE UPLOAD */}
                <aside className="space-y-4">
                  <div className="border border-[#E8EEF9] rounded-xl p-5 bg-white">
                    <label htmlFor="alumni-image" className="mb-2 block text-xs font-bold text-[#0D1B3E]">
                      {tr("alumni.uploadImage", "Upload Image", "បញ្ចូលរូបភាព")}
                    </label>
                    <label
                      htmlFor="alumni-image"
                      className={`flex min-h-[130px] cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed px-4 py-5 text-center transition ${
                        uploadingImage
                          ? "cursor-not-allowed border-[#E8EEF9] bg-[#F0F7FF] opacity-60"
                          : "border-[#E8EEF9] bg-[#F0F7FF] hover:border-[#0D1B3E] hover:bg-white"
                      }`}
                    >
                      {uploadingImage ? (
                        <>
                          <span className="h-7 w-7 animate-spin rounded-full border-2 border-[#E8EEF9] border-t-[#0D1B3E]" />
                          <span className="mt-3 text-xs font-bold text-[#0D1B3E]">
                            {isKhmer ? "កំពុងបញ្ចូលរូបភាព..." : "Uploading image..."}
                          </span>
                        </>
                      ) : (
                        <>
                          <FiImage size={28} className="text-[#0D1B3E]" />
                          <span className="mt-3 text-xs font-bold text-[#0D1B3E]">
                            {isKhmer ? "ចុចដើម្បីជ្រើសរើសរូបភាព" : "Click to select an image"}
                          </span>
                          <span className="mt-1 text-[10px] text-[#6B8AFF]">JPG, PNG, WEBP — Max 5MB</span>
                        </>
                      )}
                      <input id="alumni-image" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" onChange={handleImageUpload} disabled={uploadingImage} className="hidden" />
                    </label>
                    {formData.image && (
                      <div className="mt-3 rounded-lg bg-[#F0F7FF] border border-[#E8EEF9] px-3 py-2">
                        <p className="break-all text-[10px] leading-5 text-[#0D1B3E]">{formData.image}</p>
                      </div>
                    )}
                    {(formData.image || imagePreview) && (
                      <button
                        type="button"
                        disabled={uploadingImage}
                        onClick={removeSelectedImage}
                        className="mt-3 inline-flex h-9 w-full items-center justify-center gap-2 rounded-lg border border-[#FFEBEE] bg-[#FFEBEE] text-xs font-bold text-[#C62828] transition hover:bg-[#C62828] hover:text-white disabled:cursor-not-allowed disabled:opacity-60"
                      >
                        <FiTrash2 size={14} />
                        {isKhmer ? "លុបរូបភាព" : "Remove Image"}
                      </button>
                    )}
                  </div>

                  <div className="overflow-hidden rounded-xl border border-[#E8EEF9] bg-[#F0F7FF]">
                    <div className="relative flex aspect-[4/5] items-center justify-center min-h-[200px]">
                      {imagePreview || formData.image ? (
                        <img
                          key={imagePreview || formData.image}
                          src={imagePreview || getImageUrl(formData.image)}
                          alt={isKhmer ? "មើលរូបភាពជាមុន" : "Alumni preview"}
                          className="absolute inset-0 h-full w-full object-cover"
                          onError={(event) => { event.currentTarget.style.display = "none"; }}
                        />
                      ) : (
                        <div className="flex flex-col items-center justify-center text-[#6B8AFF]">
                          <FiImage size={36} />
                          <span className="mt-2 text-xs font-semibold">
                            {tr("alumni.imagePreview", "Image Preview", "មើលរូបភាពជាមុន")}
                          </span>
                        </div>
                      )}
                      {uploadingImage && (
                        <div className="absolute inset-0 flex items-center justify-center bg-white/80 backdrop-blur-sm">
                          <div className="text-center">
                            <span className="mx-auto block h-8 w-8 animate-spin rounded-full border-4 border-[#E8EEF9] border-t-[#0D1B3E]" />
                            <p className="mt-3 text-xs font-bold text-[#0D1B3E]">
                              {isKhmer ? "កំពុងបញ្ចូល..." : "Uploading..."}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </aside>
              </div>

              <div className="mt-6 flex flex-col-reverse gap-3 border-t border-[#E8EEF9] pt-5 sm:flex-row sm:justify-end">
                <button
                  type="button"
                  onClick={resetForm}
                  disabled={saving || uploadingImage}
                  className="inline-flex h-11 items-center justify-center rounded-lg border border-[#E8EEF9] bg-white px-6 text-sm font-bold text-[#6B8AFF] transition hover:bg-[#F0F7FF] disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {tr("common.cancel", "Cancel", "បោះបង់")}
                </button>
                <button
                  type="submit"
                  disabled={saving || uploadingImage}
                  className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#C23636] px-7 text-sm font-bold text-white shadow-sm transition hover:bg-[#A92E2E] disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {saving || uploadingImage ? (
                    <>
                      <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                      {uploadingImage
                        ? isKhmer ? "កំពុងបញ្ចូលរូបភាព..." : "Uploading image..."
                        : tr("common.saving", "Saving...", "កំពុងរក្សាទុក...")}
                    </>
                  ) : (
                    <>
                      <FiCheck size={16} />
                      {editingId ? tr("alumni.updateAlumni", "Update Alumni", "ធ្វើបច្ចុប្បន្នភាពអតីតសិស្ស") : tr("alumni.createAlumni", "Create Alumni", "បង្កើតអតីតសិស្ស")}
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        )}

        {/* =====================================================
            FILTERS
        ====================================================== */}
        <div className="mb-6 bg-white border border-[#F0F4FB] rounded-xl p-4 shadow-sm">
          <div className="grid grid-cols-1 gap-3 md:grid-cols-[1fr_160px_160px_auto]">
            <div className="relative">
              <FiSearch size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6B8AFF]" />
              <input
                type="search"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder={tr("alumni.searchPlaceholder", "Search alumni...", "ស្វែងរកអតីតសិស្ស...")}
                className="h-[42px] w-full rounded-lg border border-[#E8EEF9] bg-[#F0F7FF] pl-9 pr-3 text-sm outline-none transition focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E]"
              />
            </div>
            <select
              value={statusFilter}
              onChange={(event) => setStatusFilter(event.target.value)}
              className="h-[42px] rounded-lg border border-[#E8EEF9] bg-[#F0F7FF] px-3 text-sm font-semibold text-[#0D1B3E] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E]"
            >
              <option value="all">{tr("alumni.allStatus", "All Status", "ស្ថានភាពទាំងអស់")}</option>
              <option value="active">{tr("common.active", "Active", "សកម្ម")}</option>
              <option value="inactive">{tr("common.inactive", "Inactive", "អសកម្ម")}</option>
            </select>
            <select
              value={featuredFilter}
              onChange={(event) => setFeaturedFilter(event.target.value)}
              className="h-[42px] rounded-lg border border-[#E8EEF9] bg-[#F0F7FF] px-3 text-sm font-semibold text-[#0D1B3E] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E]"
            >
              <option value="all">{tr("alumni.allAlumni", "All Alumni", "អតីតសិស្សទាំងអស់")}</option>
              <option value="featured">{tr("common.featured", "Featured", "ពិសេស")}</option>
              <option value="regular">{tr("alumni.notFeatured", "Not Featured", "មិនពិសេស")}</option>
            </select>
            <button
              type="button"
              onClick={fetchAlumni}
              disabled={loading}
              className="inline-flex h-[42px] items-center justify-center gap-2 rounded-lg border border-[#E8EEF9] bg-white px-4 text-xs font-bold text-[#0D1B3E] transition hover:border-[#0D1B3E] hover:bg-[#F0F7FF] disabled:opacity-60"
            >
              <FiRefreshCw size={14} className={loading ? "animate-spin" : ""} />
              {tr("common.refresh", "Refresh", "ផ្ទុកឡើងវិញ")}
            </button>
          </div>
        </div>

        {/* =====================================================
            LIST (TABLE)
        ====================================================== */}
        <div className="bg-white border border-[#F0F4FB] rounded-xl shadow-sm overflow-hidden">
          <div className="flex flex-col gap-2 border-b border-[#E8EEF9] px-6 py-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-[#C23636]">
                {tr("alumni.directory", "Alumni Directory", "បញ្ជីអតីតសិស្ស")}
              </p>
              <h2 className="text-lg font-bold text-[#0D1B3E] mt-0.5">
                {tr("alumni.records", "Alumni Records", "កំណត់ត្រាអតីតសិស្ស")}
              </h2>
            </div>
            <p className="text-xs font-semibold text-[#6B8AFF]">
              {tr("alumni.showing", "Showing", "កំពុងបង្ហាញ")} {filteredAlumni.length} {tr("alumni.of", "of", "ក្នុងចំណោម")} {alumni.length}
            </p>
          </div>

          {loading ? (
            <div className="flex min-h-[280px] items-center justify-center">
              <div className="text-center">
                <span className="mx-auto block h-8 w-8 animate-spin rounded-full border-4 border-[#F0F7FF] border-t-[#0D1B3E]" />
                <p className="mt-3 text-sm font-semibold text-[#6B8AFF]">
                  {tr("alumni.loading", "Loading alumni...", "កំពុងផ្ទុកអតីតសិស្ស...")}
                </p>
              </div>
            </div>
          ) : filteredAlumni.length === 0 ? (
            <div className="flex min-h-[280px] flex-col items-center justify-center px-5 text-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#F0F7FF] text-[#0D1B3E]">
                <FiAward size={28} />
              </div>
              <h3 className="mt-4 text-lg font-bold text-[#0D1B3E]">
                {tr("alumni.noAlumni", "No Alumni Found", "រកមិនឃើញអតីតសិស្ស")}
              </h3>
              <p className="mt-2 max-w-sm text-sm leading-6 text-[#6B8AFF]">
                {tr("alumni.noAlumniDescription", "Add the first alumni profile or change your filters.", "សូមបន្ថែមអតីតសិស្សដំបូង ឬកែប្រែតម្រងស្វែងរក។")}
              </p>
              <button
                type="button"
                onClick={openCreateForm}
                className="mt-5 inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#C23636] px-5 text-sm font-bold text-white transition hover:bg-[#A92E2E]"
              >
                <FiPlus size={18} />
                {tr("alumni.addAlumni", "Add Alumni", "បន្ថែមអតីតសិស្ស")}
              </button>
            </div>
          ) : (
            <>
              {/* Desktop table */}
              <div className="hidden overflow-x-auto lg:block">
                <table className="w-full min-w-[1050px] border-collapse">
                  <thead>
                    <tr className="bg-[#F0F7FF] text-left">
                      {[
                        "Alumni",
                        "Role & Company",
                        "Graduation",
                        "Order",
                        tr("common.featured", "Featured", "ពិសេស"),
                        "Status",
                        "Actions",
                      ].map((heading) => (
                        <th key={heading} className="border-b border-[#E8EEF9] px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-[#6B8AFF]">
                          {heading}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredAlumni.map((item) => (
                      <tr key={item.id} className="border-b border-[#F0F4FB] transition last:border-b-0 hover:bg-[#F0F7FF]/50">
                        <td className="px-5 py-4">
                          <div className="flex min-w-[230px] items-center gap-3">
                            <div className="relative h-12 w-12 flex-none overflow-hidden rounded-xl bg-[#F0F7FF]">
                              {item.image ? (
                                <img src={getImageUrl(item.image)} alt={localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))} className="h-full w-full object-cover" onError={(event) => { event.currentTarget.style.display = "none"; }} />
                              ) : null}
                              <div className="absolute inset-0 flex items-center justify-center text-[#6B8AFF]">
                                <FiUser size={20} />
                              </div>
                            </div>
                            <div className="min-w-0">
                              <p className="truncate text-sm font-bold text-[#0D1B3E]">
                                {localized(item, "name", "—")}
                              </p>
                              <p className="mt-1 truncate text-xs text-[#6B8AFF]">
                                {isKhmer ? item.name_en || "—" : item.name_km || "—"}
                              </p>
                            </div>
                          </div>
                        </td>
                        <td className="px-5 py-4">
                          <div className="max-w-[260px]">
                            <p className="truncate text-xs font-semibold text-[#0D1B3E]">
                              {localized(item, "role", "—")}
                            </p>
                            <p className="mt-1 truncate text-xs text-[#6B8AFF]">
                              {localized(item, "company", "—")}
                            </p>
                          </div>
                        </td>
                        <td className="px-5 py-4 text-xs font-semibold text-[#0D1B3E]">
                          {item.graduation_year || "—"}
                        </td>
                        <td className="px-5 py-4 text-xs font-semibold text-[#0D1B3E]">
                          {item.order ?? 0}
                        </td>
                        <td className="px-5 py-4">
                          <button
                            type="button"
                            onClick={() => handleQuickUpdate(item, "is_featured")}
                            className={`inline-flex h-8 items-center gap-1.5 rounded-full px-3 text-[10px] font-bold transition ${
                              item.is_featured
                                ? "bg-[#FFF3E0] text-[#E65100] hover:bg-[#FFE0B2]"
                                : "bg-[#F0F7FF] text-[#6B8AFF] hover:bg-[#E8EEF9]"
                            }`}
                          >
                            <FiStar size={13} className={item.is_featured ? "fill-current" : ""} />
                            {item.is_featured ? tr("common.featured", "Featured", "ពិសេស") : "Regular"}
                          </button>
                        </td>
                        <td className="px-5 py-4">
                          <button
                            type="button"
                            onClick={() => handleQuickUpdate(item, "is_active")}
                            className={`inline-flex h-8 items-center rounded-full px-3 text-[10px] font-bold transition ${
                              item.is_active
                                ? "bg-[#EBF9F0] text-[#2E7D32] hover:bg-[#C8E6C9]"
                                : "bg-[#FFEBEE] text-[#C62828] hover:bg-[#FFCDD2]"
                            }`}
                          >
                            {item.is_active ? tr("common.active", "Active", "សកម្ម") : tr("common.inactive", "Inactive", "អសកម្ម")}
                          </button>
                        </td>
                        <td className="px-5 py-4">
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => openEditForm(item)}
                              className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#F0F7FF] text-[#0D1B3E] transition hover:bg-[#0D1B3E] hover:text-white"
                              title={tr("common.edit", "Edit", "កែប្រែ")}
                            >
                              <FiEdit2 size={15} />
                            </button>
                            <button
                              type="button"
                              onClick={() => handleDelete(item)}
                              disabled={deletingId === item.id}
                              className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#FFEBEE] text-[#C62828] transition hover:bg-[#C62828] hover:text-white disabled:cursor-not-allowed disabled:opacity-60"
                              title={tr("common.delete", "Delete", "លុប")}
                            >
                              {deletingId === item.id ? (
                                <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                              ) : (
                                <FiTrash2 size={15} />
                              )}
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Mobile / tablet cards */}
              <div className="grid grid-cols-1 gap-4 p-4 sm:grid-cols-2 lg:hidden">
                {filteredAlumni.map((item) => (
                  <div key={item.id} className="overflow-hidden rounded-xl border border-[#F0F4FB] bg-white shadow-sm">
                    <div className="relative h-[210px] bg-[#F0F7FF]">
                      {item.image ? (
                        <img src={getImageUrl(item.image)} alt={localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))} className="h-full w-full object-cover" onError={(event) => { event.currentTarget.style.display = "none"; }} />
                      ) : (
                        <div className="flex h-full items-center justify-center text-[#E8EEF9]">
                          <FiUser size={44} />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-[#0D1B3E]/80 via-transparent to-transparent" />
                      <div className="absolute left-3 top-3 flex gap-2">
                        {item.is_featured && (
                          <span className="rounded-full bg-[#FFB300] px-2.5 py-1 text-[9px] font-bold text-[#0D1B3E]">
                            Featured
                          </span>
                        )}
                        <span className={`rounded-full px-2.5 py-1 text-[9px] font-bold text-white ${item.is_active ? "bg-[#2E7D32]" : "bg-[#C62828]"}`}>
                          {item.is_active ? tr("common.active", "Active", "សកម្ម") : tr("common.inactive", "Inactive", "អសកម្ម")}
                        </span>
                      </div>
                      <div className="absolute inset-x-0 bottom-0 p-4 text-white">
                        <h3 className="text-base font-bold">
                          {localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))}
                        </h3>
                        <p className="mt-1 text-xs text-white/80">
                          {isKhmer ? item.name_en || "" : item.name_km || ""}
                        </p>
                      </div>
                    </div>
                    <div className="p-4">
                      <p className="text-xs font-semibold text-[#C23636]">
                        {localized(item, "role", "—")}
                      </p>
                      <p className="mt-1 text-xs text-[#6B8AFF]">
                        {localized(item, "company", "—")}
                      </p>
                      <div className="mt-4 flex items-center justify-between border-t border-[#E8EEF9] pt-4">
                        <span className="text-[10px] font-semibold text-[#6B8AFF]">
                          {tr("alumni.graduation", "Graduation", "ឆ្នាំបញ្ចប់ការសិក្សា")}: {item.graduation_year || "—"}
                        </span>
                        <div className="flex gap-2">
                          <button type="button" onClick={() => openEditForm(item)} className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#F0F7FF] text-[#0D1B3E]">
                            <FiEdit2 size={15} />
                          </button>
                          <button type="button" onClick={() => handleDelete(item)} disabled={deletingId === item.id} className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#FFEBEE] text-[#C62828] disabled:opacity-60">
                            {deletingId === item.id ? (
                              <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                            ) : (
                              <FiTrash2 size={15} />
                            )}
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

// ==========================================
// SUB COMPONENTS
// ==========================================

const InputField = ({ label, name, value, onChange, type = "text", required = false, placeholder = "", min, max, wrapperClassName = "" }) => {
  return (
    <div className={wrapperClassName}>
      <label htmlFor={name} className="mb-1.5 block text-[11px] font-bold text-[#0D1B3E]">
        {label}
        {required && <span className="ml-1 text-[#C23636]">*</span>}
      </label>
      <input
        id={name}
        name={name}
        type={type}
        value={value}
        onChange={onChange}
        required={required}
        placeholder={placeholder}
        min={min}
        max={max}
        className="h-[44px] w-full rounded-lg border border-[#E8EEF9] bg-[#F0F7FF] px-3 text-sm text-[#0D1B3E] outline-none transition placeholder:text-[#6B8AFF] focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E]"
      />
    </div>
  );
};

const TextareaField = ({ label, name, value, onChange, placeholder = "", wrapperClassName = "" }) => {
  return (
    <div className={wrapperClassName}>
      <label htmlFor={name} className="mb-1.5 block text-[11px] font-bold text-[#0D1B3E]">
        {label}
      </label>
      <textarea
        id={name}
        name={name}
        value={value}
        onChange={onChange}
        rows={5}
        placeholder={placeholder}
        className="min-h-[130px] w-full resize-y rounded-lg border border-[#E8EEF9] bg-[#F0F7FF] px-3 py-3 text-sm leading-6 text-[#0D1B3E] outline-none transition placeholder:text-[#6B8AFF] focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E]"
      />
    </div>
  );
};

const CheckboxField = ({ label, name, checked, onChange }) => {
  return (
    <label htmlFor={name} className="flex cursor-pointer items-center justify-between gap-4">
      <span className="text-xs font-bold text-[#0D1B3E]">{label}</span>
      <span className="relative inline-flex">
        <input id={name} name={name} type="checkbox" checked={checked} onChange={onChange} className="peer sr-only" />
        <span className="h-6 w-11 rounded-full bg-[#E8EEF9] transition peer-checked:bg-[#0D1B3E]" />
        <span className="absolute left-1 top-1 h-4 w-4 rounded-full bg-white shadow-sm transition peer-checked:translate-x-5" />
      </span>
    </label>
  );
};

export default AdminAlumni;
